import{_ as l}from"./chunks/plate-navigation.DRgsKBSY.js";import{_ as i}from"./chunks/3d-plate.D8HyllIX.js";import{_ as o,c as n,o as s,j as e,ag as r,a}from"./chunks/framework.DZ_cNctr.js";const h="/docs/screenshots/plate-well-view.png",b=JSON.parse('{"title":"HCS Plates","description":"Open and navigate high-content screening plates in OME-Zarr. Switch between field, well and plate views, jump between wells, open any field in 3D, and choose which field the plate overview shows.","frontmatter":{"title":"HCS Plates","description":"Open and navigate high-content screening plates in OME-Zarr. Switch between field, well and plate views, jump between wells, open any field in 3D, and choose which field the plate overview shows."},"headers":[],"relativePath":"guides/hcs-plates.md","filePath":"guides/hcs-plates.md"}'),p={name:"guides/hcs-plates.md"};function d(c,t,m,w,u,g){return s(),n("div",null,[...t[0]||(t[0]=[e("h1",{id:"hcs-plates",tabindex:"-1"},[a("HCS Plates "),e("a",{class:"header-anchor",href:"#hcs-plates","aria-label":'Permalink to "HCS Plates"'},"​")],-1),e("p",null,[a("Find Nuclei Viewer supports High-Content Screening (HCS) plate data in OME-ZARR format. Any plate format works: 96, 384, 1536-well, and custom layouts. Imaged in several z-planes? "),e("a",{href:"#plates-in-3d"},"Any field opens in 3D"),a(", with the well map still beside it.")],-1),e("div",{style:{position:"relative","padding-bottom":"56.25%",height:"0",overflow:"hidden",margin:"1.5rem 0"}},[e("iframe",{src:"https://www.youtube.com/embed/tTUhXRHREnU?rel=0&modestbranding=1&vq=hd720&mute=1",title:"HCS Plate in Your Browser",style:{position:"absolute",top:"0",left:"0",width:"100%",height:"100%",border:"0"},allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:""})],-1),r('<p>Once the plate is open, the question is usually which cells responded. <a href="https://www.find-nuclei.com/blog/hcs-analytics-in-the-browser" target="_blank" rel="noreferrer">HCS Analytics in the Browser: 18,648 Nuclei, Zero Uploads</a> takes a segmented BBBC013 screen and answers that without leaving the image, which is the part a scatter plot cannot do.</p><h2 id="opening-a-plate" tabindex="-1">Opening a plate <a class="header-anchor" href="#opening-a-plate" aria-label="Permalink to &quot;Opening a plate&quot;">​</a></h2><p>Open an HCS plate the same way as any other OME-ZARR dataset. Drag and drop, or paste a URL. The viewer detects the plate metadata and switches the sidebar to plate navigation.</p><h2 id="view-modes" tabindex="-1">View modes <a class="header-anchor" href="#view-modes" aria-label="Permalink to &quot;View modes&quot;">​</a></h2><p>A plate is three things at once: a single field, a well, and the whole layout. The <strong>Field / Well / Plate</strong> toggle at the top of the Navigation tab moves between them, and the rest of the panel follows whichever one is active.</p><p><img width="850" height="786" src="'+l+'" alt="The Navigation tab on a 384-well plate, showing the Field / Well / Plate toggle with Plate active, the well navigator reading Well A/1, and the collapsible plate grid below" style="max-width:425px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><p><strong>Field</strong> shows one field, exactly like any single image. Zoom, pan, and adjust channels as usual. This is where a plate opens, on the first field of the first populated well. A field with z-sections can also <a href="#plates-in-3d">open in 3D</a>.</p><p><strong>Well</strong> lays out every field of the current well side by side, so you can judge the whole well at once. It becomes available as soon as a well holds more than one field. On the 384-well plate above each well has a single field, which is why Well is greyed out there.</p><p><img width="3000" height="1900" src="'+h+'" alt="Well view showing all twenty fields of well L/24 arranged in a grid, each tile labelled F0 to F19, with the Well button active in the toggle" style="max-width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><p><strong>Plate</strong> renders every populated well in the plate layout, giving you the whole screen in one view. From here you can zoom smoothly all the way back down to individual cells: the viewer loads the right resolution across wells and fields as you go, so the plate overview and a single nucleus are the same continuous view.</p><h2 id="plates-in-3d" tabindex="-1">Plates in 3D <a class="header-anchor" href="#plates-in-3d" aria-label="Permalink to &quot;Plates in 3D&quot;">​</a></h2><p>If your plate was imaged in several z-planes, every field is a volume. Open it in 3D and you keep the plate around it: no export, and nothing to install.</p><figure style="margin:1rem 0;"><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fuk1s3.embassy.ebi.ac.uk%2Fidr%2Fzarr%2Fv0.5%2Fidr0090%2F190129.zarr&amp;z=22&amp;c=0%3Aoff%3AFFFFFF%3Aauto%3A1.00%2C1%3Aon%3A0000FF%3A415%3A475%3A1.00%2C2%3Aoff%3A00FF00%3Aauto%3A1.00%2C3%3Aon%3AFF0000%3A145%3A349%3A1.00%2C4%3Aon%3A00FF00%3A277%3A1075%3A1.00&amp;v=field&amp;w=B%2F2&amp;f=0&amp;zm=-0.96&amp;xy=1024%2C1022&amp;cm=C&amp;inv=f&amp;bg=%23000000&amp;pj=none%3A0%3A30&amp;l=&amp;l3s=&amp;mode=3d&amp;layout=main&amp;main=v3d&amp;sync=0&amp;syncpos=0&amp;cam=58.13%2C79.83%2C20.09%2C1.672%2C0.283%2C-0.6028%2C0.746%2C0.3356%2C-0.6664%2C-0.6658&amp;ramp=1%3A403%3A466%2C3%3A113%3A298%2C4%3A134%3A831"><img src="'+i+'" alt="One field of a plate in 3D: the volume in three colours, the planes beside it, and the Navigation panel with Field view, Well B/2 and the well map" width="1400" height="1204" style="max-width:100%;height:auto;border:1px solid var(--vp-c-divider);border-radius:8px;display:block;"></a><figcaption style="font-size:0.85em;color:var(--vp-c-text-2);margin-top:0.4rem;"><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fuk1s3.embassy.ebi.ac.uk%2Fidr%2Fzarr%2Fv0.5%2Fidr0090%2F190129.zarr&amp;z=22&amp;c=0%3Aoff%3AFFFFFF%3Aauto%3A1.00%2C1%3Aon%3A0000FF%3A415%3A475%3A1.00%2C2%3Aoff%3A00FF00%3Aauto%3A1.00%2C3%3Aon%3AFF0000%3A145%3A349%3A1.00%2C4%3Aon%3A00FF00%3A277%3A1075%3A1.00&amp;v=field&amp;w=B%2F2&amp;f=0&amp;zm=-0.96&amp;xy=1024%2C1022&amp;cm=C&amp;inv=f&amp;bg=%23000000&amp;pj=none%3A0%3A30&amp;l=&amp;l3s=&amp;mode=3d&amp;layout=main&amp;main=v3d&amp;sync=0&amp;syncpos=0&amp;cam=58.13%2C79.83%2C20.09%2C1.672%2C0.283%2C-0.6028%2C0.746%2C0.3356%2C-0.6664%2C-0.6658&amp;ramp=1%3A403%3A466%2C3%3A113%3A298%2C4%3A134%3A831" style="font-weight:600;">Open this view</a><br>Well B/2 of a 96-well plate in 3D, three of its five channels (IDR idr0090, CC BY 4.0). </figcaption></figure><ol><li>Pick a well and a field, in <strong>Field</strong> view.</li><li>Click <strong>3D</strong> in the Navigation panel.</li><li>Move to the next well with the well map or the arrows. That field opens in 3D at the same z and time point.</li></ol><p>A <a href="./region.html">region</a> and <a href="./3d-rendering.html#labels-in-3d">labels</a> work here too. <strong>Well</strong> and <strong>Plate</strong> views stay in 2D. See <a href="./3d-rendering.html#plates-in-3d">Plates in 3D</a> for the details.</p><h2 id="moving-between-wells" tabindex="-1">Moving between wells <a class="header-anchor" href="#moving-between-wells" aria-label="Permalink to &quot;Moving between wells&quot;">​</a></h2><p>The navigator under the toggle steps through populated wells with the arrows, and tells you where you are: <code>Well L/24 · 36 of 72</code>. It counts populated wells only, so there are no empty stops to click past.</p><p>Below it, the plate grid draws the full layout with populated wells picked out. Click any well to jump straight to it. It collapses with the arrow on its header when you want the room.</p><p>When a well holds several fields, a field dropdown appears next to the well name. What it does depends on the mode:</p><ul><li>In <strong>Field</strong> view it picks which field you are looking at.</li><li>In <strong>Plate</strong> view it picks which field index represents every well in the overview, so you can compare the same field position across the whole plate.</li></ul><h2 id="labelling-the-tiles" tabindex="-1">Labelling the tiles <a class="header-anchor" href="#labelling-the-tiles" aria-label="Permalink to &quot;Labelling the tiles&quot;">​</a></h2><p>In Well and Plate view, the <strong>Label</strong> control in the status bar chooses the text drawn on each tile: field ID (<code>F0</code>, <code>F1</code>, <code>F2</code>), well ID (<code>A1</code>, <code>B3</code>, <code>G11</code>), or none. If the plate carries well annotations, those appear as options too, so the grid can be labelled by dose, compound, or any other column your plate metadata provides.</p><h2 id="channels-across-the-plate" tabindex="-1">Channels across the plate <a class="header-anchor" href="#channels-across-the-plate" aria-label="Permalink to &quot;Channels across the plate&quot;">​</a></h2><p>Channel settings apply to every well and field at once. Pick a colour or set a contrast window in Field view and the whole plate follows, which is what makes a Plate view comparable across wells. All the controls work the same as anywhere else, so see the <a href="./channels.html">Channels guide</a> for what each one does.</p><h2 id="labels-and-analytics" tabindex="-1">Labels and analytics <a class="header-anchor" href="#labels-and-analytics" aria-label="Permalink to &quot;Labels and analytics&quot;">​</a></h2><p>Segmentation masks work on plates, discovered across wells and rendered consistently on every field. Because scanning a plate for masks is a per-well operation, plates ask before they scan rather than doing it on open. The <a href="./labels.html">Labels guide</a> covers that, and <a href="./analytics-phenotyping.html">Analytics &amp; Phenotyping</a> covers colouring objects by measurement, which is where a plate becomes a plot.</p><h2 id="live-examples" tabindex="-1">Live Examples <a class="header-anchor" href="#live-examples" aria-label="Permalink to &quot;Live Examples&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Example</th><th>Description</th></tr></thead><tbody><tr><td><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fuk1s3.embassy.ebi.ac.uk%2Fidr%2Fzarr%2Fv0.5%2Fidr0090%2F190129.zarr&amp;z=15&amp;channels=0%3Aoff%3AFFFFFF%3A617%3A1676%2C1%3Aon%3A0000FF%3A403%3A441%2C2%3Aoff%3A00FF00%3A109%3A148%2C3%3Aon%3AFF0000%3A113%3A254%2C4%3Aon%3A00FF00%3A132%3A720&amp;zoom=-1.38&amp;center=1024%2C1022" target="_blank" rel="noreferrer">HCS Plate (v0.5, 5ch)</a></td><td>Multi-well plate, 5 channels, v0.5</td></tr><tr><td><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fuk1s3.embassy.ebi.ac.uk%2Fidr%2Fzarr%2Fv0.5%2Fidr0090%2F190129.zarr&amp;z=22&amp;c=0%3Aoff%3AFFFFFF%3Aauto%3A1.00%2C1%3Aon%3A0000FF%3A415%3A475%3A1.00%2C2%3Aoff%3A00FF00%3Aauto%3A1.00%2C3%3Aon%3AFF0000%3A145%3A349%3A1.00%2C4%3Aon%3A00FF00%3A277%3A1075%3A1.00&amp;v=field&amp;w=B%2F2&amp;f=0&amp;zm=-0.96&amp;xy=1024%2C1022&amp;cm=C&amp;inv=f&amp;bg=%23000000&amp;pj=none%3A0%3A30&amp;l=&amp;l3s=&amp;mode=3d&amp;layout=main&amp;main=v3d&amp;sync=0&amp;syncpos=0&amp;cam=58.13%2C79.83%2C20.09%2C1.672%2C0.283%2C-0.6028%2C0.746%2C0.3356%2C-0.6664%2C-0.6658&amp;ramp=1%3A403%3A466%2C3%3A113%3A298%2C4%3A134%3A831" target="_blank" rel="noreferrer">HCS Plate in 3D</a></td><td>One field of the same 5-channel plate in 3D, with the well map beside it</td></tr><tr><td><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Fuk1s3.embassy.ebi.ac.uk%2Fidr%2Fzarr%2Fv0.4%2Fidr0072B%2F9512.zarr&amp;z=0&amp;channels=0%3Aon%3A00FF00%3A24%3A1835%2C1%3Aon%3A0000FF%3A6%3A843&amp;zoom=-0.38&amp;center=673%2C509" target="_blank" rel="noreferrer">HCS Plate (v0.4, 2ch)</a></td><td>Multi-well plate, 20 fields per well, v0.4</td></tr></tbody></table><h2 id="image-credits" tabindex="-1">Image credits <a class="header-anchor" href="#image-credits" aria-label="Permalink to &quot;Image credits&quot;">​</a></h2><p>The screenshots on this page use plates from public collections. See <a href="./../sample-data.html">Sample Data and Credits</a>.</p>',30)])])}const v=o(p,[["render",d]]);export{b as __pageData,v as default};
